package com.linkforge.domain.workflow.implementation;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.Collections;
import java.util.HexFormat;
import java.util.List;

/**
 * Structured, bounded repair patch proposal generated by the repair specialist
 * with cryptographic hashes, attempt number, and parent proposal lineage.
 */
public record RepairProposal(
        String repairId,
        int attemptNumber,
        String lineageProposalHash,
        String repairProposalHash,
        List<FileChangeProposal> changes,
        String rationale,
        boolean safe,
        String unsafeReason,
        Instant proposedAt
) {
    public RepairProposal {
        changes = changes != null ? List.copyOf(changes) : Collections.emptyList();
    }

    public static String computeHash(String lineageHash, int attemptNumber, List<FileChangeProposal> changes) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            digest.update(lineageHash != null ? lineageHash.getBytes(StandardCharsets.UTF_8) : new byte[0]);
            digest.update(String.valueOf(attemptNumber).getBytes(StandardCharsets.UTF_8));
            if (changes != null) {
                for (FileChangeProposal change : changes) {
                    digest.update(change.path().getBytes(StandardCharsets.UTF_8));
                    digest.update(change.operation().name().getBytes(StandardCharsets.UTF_8));
                    digest.update(change.proposedContent().getBytes(StandardCharsets.UTF_8));
                }
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (Exception e) {
            throw new RuntimeException("Failed to compute repair proposal hash", e);
        }
    }

    public String repairHash() {
        return repairProposalHash;
    }
}
